package com.senniaf.match;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.http.*;
import java.util.*;
import java.time.*;
import static org.junit.jupiter.api.Assertions.*;
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@org.springframework.context.annotation.Import(PruebasProgramacionConfig.class)
@EnabledIfEnvironmentVariable(named="HU19_TEST_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/hu19_[a-z_]+")
class HU13PostgresIT extends SoportePostgresIT {
 @org.springframework.beans.factory.annotation.Autowired PruebasProgramacionConfig.Reloj reloj;
 @org.springframework.beans.factory.annotation.Autowired com.senniaf.match.service.PesosProgramadosService servicioProgramado;
 static final List<String> FACTORES=List.of("edad","hermanos","salud","apoyo","logistica");
 Map<String,Integer> originales;
 JsonNode pesos(){var r=req("/api/scoring/pesos",HttpMethod.GET,comite,null);assertEquals(200,r.getStatusCode().value(),r.getBody());return datos(r);}
 JsonNode agenda(){return datos(req("/api/scoring/pesos/programacion",HttpMethod.GET,comite,null));}
 JsonNode historial(){return datos(req("/api/scoring/pesos/historial",HttpMethod.GET,comite,null));}
 Map<String,Integer> valores(JsonNode p){var m=new LinkedHashMap<String,Integer>();FACTORES.forEach(k->m.put(k,p.path(k).asInt()));return m;}
 Map<String,Object> propuesta(JsonNode p){var m=new LinkedHashMap<String,Object>(valores(p));String a=FACTORES.stream().filter(k->p.path(k).asInt()>0).findFirst().orElseThrow();String b=FACTORES.stream().filter(k->!k.equals(a)).findFirst().orElseThrow();m.put(a,p.path(a).asInt()-1);m.put(b,p.path(b).asInt()+1);m.put("versionEsperada",p.path("version").asInt());m.put("justificacion","Cambio sintético justificado para probar programación segura de criterios");return m;}
 void activar(){var p=agenda().path("pendiente");if(!p.isNull()&&!p.isMissingNode())reloj.avanzar(Instant.parse(p.path("activarEl").asText()).plusSeconds(2));pesos();}
 @BeforeEach void conservar(){reloj.dias(5);activar();originales=valores(pesos());}
 @AfterEach void restaurarConHistoria(){activar();var p=pesos();if(!originales.equals(valores(p))){var m=new LinkedHashMap<String,Object>(originales);m.put("versionEsperada",p.path("version").asInt());m.put("justificacion","Restablecer los valores sintéticos iniciales conservando toda la auditoría");assertEquals(200,req("/api/scoring/pesos",HttpMethod.PUT,comite,m).getStatusCode().value());activar();}assertEquals(originales,valores(pesos()));}
 @Test void programacionNoCambiaVigentesYActivacionConservaResponsableFechasEHistoria(){
  var c=caso();assertEquals(200,aceptar(c.n(),c.f()).getStatusCode().value());var d=decisiones.findByCodigoFamiliaOrderByFechaAsc(c.f().getCodigoCaso()).get(0);var contexto=d.getContextoScoring();int puntuacion=d.getPuntaje();
  var antes=pesos();int n=historial().size();var m=propuesta(antes);var r=req("/api/scoring/pesos",HttpMethod.PUT,comite,m);assertEquals(200,r.getStatusCode().value(),r.getBody());var plan=datos(r);
  assertEquals("PENDIENTE",plan.path("estado").asText());assertEquals(antes,pesos());assertEquals(n+1,historial().size());assertEquals("HU19-CM",plan.path("responsable").asText());assertEquals(m.get("justificacion"),plan.path("justificacion").asText());assertEquals(json.valueToTree(valores(antes)),plan.path("anteriores"));
  Instant prevista=Instant.parse(plan.path("activarEl").asText());assertFalse(prevista.isBefore(reloj.instant().plus(Duration.ofHours(24))));assertEquals(LocalTime.of(7,0),prevista.atZone(ZoneId.of("America/Panama")).toLocalTime());
  reloj.avanzar(prevista.minusSeconds(1));assertEquals(antes,pesos());reloj.avanzar(prevista.plusSeconds(120));var nuevo=pesos();assertEquals(antes.path("version").asInt()+1,nuevo.path("version").asInt());FACTORES.forEach(k->assertEquals(m.get(k),nuevo.path(k).asInt()));assertEquals(n+2,historial().size());var evento=java.util.stream.StreamSupport.stream(historial().spliterator(),false).map(x->x.path("cambio")).filter(x->x.path("id").asLong()==plan.path("id").asLong()&&"APLICADA".equals(x.path("estado").asText())).findFirst().orElseThrow();assertEquals("APLICADA",evento.path("estado").asText());assertEquals(prevista.toString(),evento.path("activarEl").asText());assertEquals(reloj.instant().toString(),evento.path("activadaEl").asText());assertEquals(contexto,decisiones.findById(d.getId()).orElseThrow().getContextoScoring());assertEquals(puntuacion,decisiones.findById(d.getId()).orElseThrow().getPuntaje());
 }
 @Test void rechazaValoresInvalidosSinModificarPesosNiAuditoria(){var p=pesos();var h=historial();var casos=new ArrayList<Map<String,Object>>();for(Object v:Arrays.asList(-1,101,20.5,"20",true,null)){var m=propuesta(p);m.put("edad",v);casos.add(m);}var suma=propuesta(p);suma.put("edad",(Integer)suma.get("edad")+1);casos.add(suma);var falta=propuesta(p);falta.remove("salud");casos.add(falta);var extra=propuesta(p);extra.put("cultura",0);casos.add(extra);for(Object v:Arrays.asList("corto"," ".repeat(15),"a".repeat(301),null,123)){var m=propuesta(p);m.put("justificacion",v);casos.add(m);}for(Object v:Arrays.asList(null,"1",1.5,true)){var m=propuesta(p);m.put("versionEsperada",v);casos.add(m);}for(var m:casos){assertEquals(400,req("/api/scoring/pesos",HttpMethod.PUT,comite,m).getStatusCode().value());assertEquals(p,pesos());assertEquals(h,historial());}}
 @Test void pendientesYVersionesDesactualizadasNoSobrescribenCambios(){var p=pesos();var m=propuesta(p);assertEquals(200,req("/api/scoring/pesos",HttpMethod.PUT,comite,m).getStatusCode().value());var h=historial();assertEquals(409,req("/api/scoring/pesos",HttpMethod.PUT,comite,m).getStatusCode().value());assertEquals(h,historial());activar();h=historial();assertEquals(409,req("/api/scoring/pesos",HttpMethod.PUT,comite,m).getStatusCode().value());assertEquals(h,historial());}
 @Test void servidorRechazaOtrosRolesInclusoSiFalsificanCabeceras(){var c=caso();var p=pesos();var h=historial();for(String t:List.of(social,psicologo,c.token())){for(String ruta:List.of("/api/scoring/pesos","/api/scoring/pesos/historial","/api/scoring/pesos/programacion"))assertEquals(403,req(ruta,HttpMethod.GET,t,null).getStatusCode().value());var cab=new HttpHeaders();cab.setContentType(MediaType.APPLICATION_JSON);cab.setBearerAuth(t);cab.set("X-User-Role","COMITE");cab.set("X-User-Id","HU19-CM");assertEquals(403,http.exchange("/api/scoring/pesos",HttpMethod.PUT,new HttpEntity<>(propuesta(p),cab),String.class).getStatusCode().value());}assertEquals(401,req("/api/scoring/pesos",HttpMethod.PUT,null,propuesta(p)).getStatusCode().value());assertEquals(p,pesos());assertEquals(h,historial());}
 @Test void dosProgramacionesSimultaneasSoloRegistranUna() throws Exception {var p=pesos();int n=historial().size();var m=propuesta(p);assertEquals(List.of(200,409),simultaneas(()->req("/api/scoring/pesos",HttpMethod.PUT,comite,m),()->req("/api/scoring/pesos",HttpMethod.PUT,comite,m)));assertEquals(n+1,historial().size());assertEquals(p,pesos());}
 @Test void activacionRetrasadaConcurrenteSeEjecutaUnaSolaVez() throws Exception {var p=pesos();int n=historial().size();assertEquals(200,req("/api/scoring/pesos",HttpMethod.PUT,comite,propuesta(p)).getStatusCode().value());reloj.avanzar(Instant.parse(agenda().path("pendiente").path("activarEl").asText()).plusSeconds(600));assertEquals(List.of(200,200),simultaneas(()->req("/api/scoring/pesos",HttpMethod.GET,comite,null),()->req("/api/scoring/pesos",HttpMethod.GET,comite,null)));assertEquals(p.path("version").asInt()+1,pesos().path("version").asInt());assertEquals(n+2,historial().size());pesos();assertEquals(n+2,historial().size());}
 @Test void decisionesConAnalisisViejoNoCreanRegistrosNiVinculaciones(){var c=caso();var p=pesos();assertEquals(200,req("/api/scoring/pesos",HttpMethod.PUT,comite,propuesta(p)).getStatusCode().value());activar();long n=decisiones.count(),v=vinculaciones.count();for(String d:List.of("ACEPTADA","DESCARTADA","REEVALUACION")){var r=req("/api/scoring/casos/"+c.n().getCodigoCaso()+"/decisiones",HttpMethod.POST,comite,Map.of("familia",c.f().getCodigoCaso(),"decision",d,"motivo","Revisión sintética con análisis desactualizado","versionPesos",p.path("version").asInt()));assertEquals(409,r.getStatusCode().value());assertTrue(datos(r).path("mensaje").asText().contains("Actualiza el análisis"));}assertEquals(n,decisiones.count());assertEquals(v,vinculaciones.count());assertEquals(200,aceptar(c.n(),c.f()).getStatusCode().value());}
 @Test void planificadorActivaSinConsultasDeInterfazYNoDuplica(){
  var p=pesos();int n=historial().size();var r=req("/api/scoring/pesos",HttpMethod.PUT,comite,propuesta(p));assertEquals(200,r.getStatusCode().value());long id=datos(r).path("id").asLong();reloj.avanzar(Instant.parse(datos(r).path("activarEl").asText()).plusSeconds(90));
  servicioProgramado.comprobarActivaciones();
  assertEquals(p.path("version").asInt()+1,jdbc.queryForObject("select version from pesos_scoring where id=1",Integer.class));assertEquals("APLICADA",jdbc.queryForObject("select estado from programaciones_pesos where id=?",String.class,id));
  servicioProgramado.comprobarActivaciones();assertEquals(n+2,historial().size());
 }

}
